$(document).ready(function() {
	$("#btnClose").click(function() {
		self.close();
	});

	$("#btnMatInfo").click(function() {
		fn_open_popup("/popup/matInfoPop.do?zzbidinv="+$("#zzbidinv").val()+"&zzstnum="+$("#zzstnum").val()+"&zzintind1="+$("#zzintind1").val(), 800, 400, "CEN");
	});

	$("#btnUnit").click(function() {
		fn_open_popup("/popup/unitCost.do?zzbidinv="+$("#zzbidinv").val()+"&zzstnum="+$("#zzstnum").val(), 800, 400, "CEN");
	});

	$("#btnLicense").click(function() {
		fn_pop_submit();
	});
	$("#zzbidinv_old_t").click(function() {

		if($("#zzbidinv_old").val() != ""){
			fnSearch2($("#zzbidinv_old").val(),$("#zzstnum_old").val());
		}
	});

	fnSearch();

});

function fnSearch2(zzbidinv_old,zzstnum_old) {
	ptab = new Array();
	finfo = new Object();

	ptab = fn_add_param(ptab, "I_ZBIDINV", zzbidinv_old , false);
	ptab = fn_add_param(ptab, "I_ZESTNUMM", zzstnum_old , false);

	//ptab = fn_add_param(ptab, "I_ZBIDINV", "9200043-00" , false);
	//ptab = fn_add_param(ptab, "I_ZESTNUMM", "00" , false);
 	finfo = {"ZFUNCNM" : "ZMME_EBID_INFO_0010F"};

 	$.ajax({
	    type:'POST',
	    url:"/comnRfc.do",
	    dataType: "json",
		data : {"p":JSON.stringify(ptab)
		        ,"fn":JSON.stringify(finfo)},
		async:false,
		success: function (data) {
			data = JSON.parse(data.data);
			setRowData(data);
		},
		error: function (e) {
			alert('펑션을 실행할 수 없습니다.');
		}
	});
}

